```go
// Package mpquic implements a QUIC-like multipath sender that stripes
// datagrams over two paths with independent RTT, loss and congestion state.
//
// The sender is written to be correct under two adversarial conditions that
// the task calls out explicitly:
//
//  1. ACK reordering. Acknowledgments may arrive out of order, so the
//     packet-threshold loss rule can fire for a packet whose ACK is still in
//     flight. The sender therefore keeps a *bounded* record of recently lost
//     packets so a late ACK can cancel the queued retransmission instead of
//     producing a spurious retransmit.
//
//  2. Abrupt path migration. When a path is invalidated, every unacknowledged
//     packet on it is moved into a bounded "migrating" set and its congestion
//     budget is released immediately. The frames are only rescheduled after a
//     PTO grace period, so an ACK that races with the migration cancels the
//     retransmission, while the grace timer guarantees forward progress if the
//     ACK never comes (no deadlock).
package mpquic

import (
	"errors"
	"sort"
	"time"
)

// PathID identifies a network path.
type PathID uint8

const (
	PathA PathID = 0
	PathB PathID = 1
)

const (
	// MaxDatagramSize is the fixed payload size used by the sender.
	MaxDatagramSize = 1200
	// MinCwnd is the floor for a path's congestion window.
	MinCwnd = 2 * MaxDatagramSize
)

// Config tunes the sender.
type Config struct {
	InitialRTT      time.Duration
	InitialCwnd     int
	PacketThreshold uint64  // reordering tolerance before a lower PN is declared lost
	TimeThreshold   float64 // multiplier of max(SRTT, latest RTT) for time-based loss
	MaxAckDelay     time.Duration
	// MaxReorderingPackets bounds the number of recently-lost packets kept
	// around so late ACKs can cancel retransmissions. This is the "bounded
	// reordering memory" of the sender.
	MaxReorderingPackets int
	// MaxConnectionInFlight, when > 0, caps the total bytes in flight across
	// all *active* paths. Migrating bytes are deliberately not counted.
	MaxConnectionInFlight int
	// MaxSendBuffer bounds the number of application frames waiting to be sent.
	MaxSendBuffer int
}

// DefaultConfig returns a conservative, production-shaped default.
func DefaultConfig() Config {
	return Config{
		InitialRTT:            100 * time.Millisecond,
		InitialCwnd:           10 * MaxDatagramSize,
		PacketThreshold:       3,
		TimeThreshold:         9.0 / 8.0,
		MaxAckDelay:           25 * time.Millisecond,
		MaxReorderingPackets:  512,
		MaxConnectionInFlight: 0,
		MaxSendBuffer:         1024,
	}
}

// Frame is an application data unit. ID must be unique per frame so that a
// retransmission can be matched back to the original.
type Frame struct {
	ID   uint64
	Data []byte
}

// Range is an inclusive range of packet numbers.
type Range struct {
	Smallest uint64
	Largest  uint64
}

// AckFrame is a (possibly non-contiguous) acknowledgment. Ranges are strictly
// below Largest. The sender tests outstanding packets for membership rather
// than expanding the ranges, so a malicious ACK cannot blow up memory.
type AckFrame struct {
	Largest uint64
	Ranges  []Range
}

func (a AckFrame) contains(pn uint64) bool {
	if pn == a.Largest {
		return true
	}
	for i := range a.Ranges {
		r := a.Ranges[i]
		if pn >= r.Smallest && pn <= r.Largest {
			return true
		}
	}
	return false
}

// ---------------------------------------------------------------------------
// RTT estimation
// ---------------------------------------------------------------------------

type rttEstimator struct {
	inited bool
	srtt   time.Duration
	rttvar time.Duration
	latest time.Duration
}

func (r *rttEstimator) update(sample time.Duration) {
	if sample <= 0 {
		return
	}
	if !r.inited {
		r.srtt = sample
		r.rttvar = sample / 2
		r.inited = true
	} else {
		diff := r.srtt - sample
		if diff < 0 {
			diff = -diff
		}
		r.rttvar = (3*r.rttvar + diff) / 4
		r.srtt = (7*r.srtt + sample) / 8
	}
	r.latest = sample
}

// pto is the probe timeout: SRTT + 4*RTTVAR + max_ack_delay.
func (r *rttEstimator) pto(maxAckDelay time.Duration) time.Duration {
	if !r.inited {
		return 0
	}
	p := r.srtt + 4*r.rttvar + maxAckDelay
	if p < 10*time.Millisecond {
		p = 10 * time.Millisecond
	}
	return p
}

// lossDelay is the time-threshold for declaring a packet lost.
func (r *rttEstimator) lossDelay(mult float64) time.Duration {
	if !r.inited {
		return 0
	}
	base := r.srtt
	if r.latest > base {
		base = r.latest
	}
	d := time.Duration(float64(base) * mult)
	if d < 10*time.Millisecond {
		d = 10 * time.Millisecond
	}
	return d
}

func (r *rttEstimator) srttOr(d time.Duration) time.Duration {
	if r.inited {
		return r.srtt
	}
	return d
}

// ---------------------------------------------------------------------------
// Per-path congestion control (NewReno)
// ---------------------------------------------------------------------------

type reno struct {
	cwnd          int
	ssthresh      int
	bytesInFlight int
	recoveryEnd   uint64
	inRecovery    bool
}

func newReno(initial int) reno {
	return reno{cwnd: initial, ssthresh: 1 << 30}
}

func (c *reno) onAck(pn uint64, ackedBytes int) {
	if c.inRecovery {
		if pn <= c.recoveryEnd {
			return // no window growth for ACKs inside a recovery period
		}
		c.inRecovery = false
	}
	if c.cwnd < c.ssthresh {
		c.cwnd += ackedBytes // slow start
	} else {
		inc := MaxDatagramSize * ackedBytes / c.cwnd
		if inc < 1 {
			inc = 1
		}
		c.cwnd += inc // congestion avoidance
	}
}

// onCongestion enters a recovery period ending at the largest PN sent when the
// loss was detected. Losses reported inside the same period do not reduce the
// window a second time.
func (c *reno) onCongestion(recoveryEnd uint64) {
	if c.inRecovery && recoveryEnd <= c.recoveryEnd {
		return
	}
	c.inRecovery = true
	c.recoveryEnd = recoveryEnd
	c.ssthresh = c.cwnd / 2
	if c.ssthresh < MinCwnd {
		c.ssthresh = MinCwnd
	}
	c.cwnd = c.ssthresh
}

// ---------------------------------------------------------------------------
// Sender state
// ---------------------------------------------------------------------------

type packet struct {
	pn        uint64
	path      PathID
	sentAt    time.Time
	size      int
	frame     Frame
	acked     bool
	lost      bool
	migrating bool
	deadline  time.Time
}

type pathState struct {
	id              PathID
	active          bool
	cc              reno
	rtt             rttEstimator
	outstanding     map[uint64]*packet
	largestSent     uint64
	largestAcked    uint64
	hasLargestAcked bool
}

// Outgoing is a datagram produced by Send.
type Outgoing struct {
	Path  PathID
	PN    uint64
	Frame Frame
	Retx  bool
}

// Stats are diagnostic counters, useful for verification.
type Stats struct {
	Sent                 int
	Retransmits          int
	SpuriousLosses       int
	MigrationRetransmits int
	CongestionEvents     int
	Acked                int
	AckFrames            int
}

// Sender is a multipath QUIC-like sender. All methods take an explicit
// timestamp so behavior is deterministic and testable.
type Sender struct {
	cfg    Config
	nextPN uint64

	paths map[PathID]*pathState

	byPN map[uint64]*packet

	// lostPackets is a bounded window of recently-lost packets. A late ACK
	// for one of them cancels the queued retransmission (spurious-loss
	// suppression). Eviction is FIFO, so memory is bounded.
	lostPackets map[uint64]*packet
	lostOrder   []uint64

	// migrating holds packets from an invalidated path. They are still in
	// byPN (so ACKs can find them) but no longer consume any path's budget.
	migrating []*packet

	newFrames []Frame
	retxOrder []uint64
	scheduled map[uint64]bool
	frames    map[uint64]Frame

	stats Stats
}

// New creates a Sender. Zero-valued config fields fall back to DefaultConfig.
func New(cfg Config) *Sender {
	d := DefaultConfig()
	if cfg.InitialRTT <= 0 {
		cfg.InitialRTT = d.InitialRTT
	}
	if cfg.InitialCwnd <= 0 {
		cfg.InitialCwnd = d.InitialCwnd
	}
	if cfg.PacketThreshold == 0 {
		cfg.PacketThreshold = d.PacketThreshold
	}
	if cfg.TimeThreshold <= 0 {
		cfg.TimeThreshold = d.TimeThreshold
	}
	if cfg.MaxAckDelay <= 0 {
		cfg.MaxAckDelay = d.MaxAckDelay
	}
	if cfg.MaxReorderingPackets <= 0 {
		cfg.MaxReorderingPackets = d.MaxReorderingPackets
	}
	if cfg.MaxSendBuffer <= 0 {
		cfg.MaxSendBuffer = d.MaxSendBuffer
	}
	return &Sender{
		cfg:         cfg,
		paths:       map[PathID]*pathState{},
		byPN:        map[uint64]*packet{},
		lostPackets: map[uint64]*packet{},
		scheduled:   map[uint64]bool{},
		frames:      map[uint64]Frame{},
	}
}

// AddPath activates a path with a fresh, independent congestion controller.
// Re-adding an already-active path is a no-op; re-adding a previously
// invalidated path installs a clean controller.
func (s *Sender) AddPath(id PathID) {
	if p, ok := s.paths[id]; ok && p.active {
		return
	}
	s.paths[id] = &pathState{
		id:          id,
		active:      true,
		cc:          newReno(s.cfg.InitialCwnd),
		outstanding: map[uint64]*packet{},
	}
}

// Enqueue queues an application frame for transmission.
func (s *Sender) Enqueue(f Frame) error {
	if len(s.newFrames) >= s.cfg.MaxSendBuffer {
		return errors.New("mpquic: send buffer full")
	}
	cp := make([]byte, len(f.Data))
	copy(cp, f.Data)
	f.Data = cp
	s.newFrames = append(s.newFrames, f)
	return nil
}

// InvalidatePath handles an abrupt migration: the path is retired and every
// unacknowledged packet is moved to the migrating set with a PTO deadline.
//
// Crucially the path's congestion budget is released at once. If those bytes
// remained "in flight", a connection-level or path-level window could be
// exhausted forever because no ACK will ever arrive for the dead path. The
// frames are not retransmitted yet: a PTO grace period lets a racing ACK
// cancel the retransmission.
func (s *Sender) InvalidatePath(now time.Time, id PathID) {
	p := s.paths[id]
	if p == nil || !p.active {
		return
	}
	p.active = false

	pto := p.rtt.pto(s.cfg.MaxAckDelay)
	if pto <= 0 {
		pto = 2*p.rtt.srttOr(s.cfg.InitialRTT) + s.cfg.MaxAckDelay
	}
	deadline := now.Add(pto)

	for pn, pkt := range p.outstanding {
		pkt.migrating = true
		pkt.deadline = deadline
		s.migrating = append(s.migrating, pkt)
		delete(p.outstanding, pn)
	}
	p.cc.bytesInFlight = 0
}

// CheckTimeouts drives the two timer-based transitions:
//   - migration grace expiry -> reschedule the frame on a surviving path;
//   - time-threshold loss on an active path -> reschedule and reduce cwnd.
func (s *Sender) CheckTimeouts(now time.Time) {
	// Migration deadlines.
	if len(s.migrating) > 0 {
		due := make([]*packet, 0, len(s.migrating))
		for _, pkt := range s.migrating {
			if !pkt.acked && !pkt.lost && !now.Before(pkt.deadline) {
				due = append(due, pkt)
			}
		}
		for _, pkt := range due {
			if s.declareLost(pkt, true) {
				s.stats.MigrationRetransmits++
			}
		}
	}

	// Time-threshold loss detection on active paths.
	for _, p := range s.paths {
		if !p.active {
			continue
		}
		delay := p.rtt.lossDelay(s.cfg.TimeThreshold)
		if delay <= 0 {
			delay = s.cfg.InitialRTT
		}
		var due []*packet
		for _, pkt := range p.outstanding {
			if now.Sub(pkt.sentAt) >= delay {
				due = append(due, pkt)
			}
		}
		for _, pkt := range due {
			s.declareLost(pkt, false)
		}
	}
}

func (s *Sender) removeMigrating(pkt *packet) {
	for i, p := range s.migrating {
		if p == pkt {
			s.migrating = append(s.migrating[:i], s.migrating[i+1:]...)
			return
		}
	}
}

// declareLost moves a packet out of flight, optionally applies a congestion
// event, remembers it in the bounded lost window, and schedules its frame for
// retransmission (once). It returns true if this call changed the packet's
// state.
func (s *Sender) declareLost(pkt *packet, fromMigration bool) bool {
	if pkt.acked || pkt.lost {
		return false
	}
	pkt.lost = true

	if pkt.migrating {
		s.removeMigrating(pkt)
	} else if p, ok := s.paths[pkt.path]; ok {
		delete(p.outstanding, pkt.pn)
		p.cc.bytesInFlight -= pkt.size
		if p.cc.bytesInFlight < 0 {
			p.cc.bytesInFlight = 0
		}
		if !fromMigration {
			// A migration is not a congestion signal: the path vanished,
			// it did not become congested.
			p.cc.onCongestion(p.largestSent)
			s.stats.CongestionEvents++
		}
	}

	delete(s.byPN, pkt.pn)
	s.rememberLost(pkt)

	if _, ok := s.scheduled[pkt.frame.ID]; !ok {
		s.scheduled[pkt.frame.ID] = true
		s.frames[pkt.frame.ID] = pkt.frame
		s.retxOrder = append(s.retxOrder, pkt.frame.ID)
	}
	return true
}

func (s *Sender) rememberLost(pkt *packet) {
	s.lostPackets[pkt.pn] = pkt
	s.lostOrder = append(s.lostOrder, pkt.pn)
	for len(s.lostOrder) > s.cfg.MaxReorderingPackets {
		old := s.lostOrder[0]
		s.lostOrder = s.lostOrder[1:]
		delete(s.lostPackets, old)
	}
}

// detectLostPath applies the packet-threshold rule within a single path. Only
// packets sent on the path that produced the ACK are considered, so
// cross-path reordering cannot cause spurious losses. Late ACKs are handled
// by the bounded lost window in OnAck.
func (s *Sender) detectLostPath(p *pathState) {
	if !p.hasLargestAcked || p.largestAcked < s.cfg.PacketThreshold {
		return
	}
	cutoff := p.largestAcked - s.cfg.PacketThreshold
	var due []*packet
	for pn, pkt := range p.outstanding {
		if pn <= cutoff {
			due = append(due, pkt)
		}
	}
	for _, pkt := range due {
		s.declareLost(pkt, false)
	}
}

// OnAck processes an ACK frame. It is safe against out-of-order and duplicate
// ACKs, and against ACKs that acknowledge packets already declared lost.
func (s *Sender) OnAck(now time.Time, ack AckFrame) {
	s.stats.AckFrames++

	// Collect live packets. Membership testing keeps memory proportional to
	// the send window regardless of how many ranges the ACK carries.
	var hits []*packet
	for pn, pkt := range s.byPN {
		if ack.contains(pn) {
			hits = append(hits, pkt)
		}
	}

	// Collect late ACKs for packets already declared lost. These are what
	// would otherwise become spurious retransmits.
	var lostHits []*packet
	for pn, pkt := range s.lostPackets {
		if ack.contains(pn) {
			lostHits = append(lostHits, pkt)
		}
	}
	for _, pkt := range lostHits {
		delete(s.scheduled, pkt.frame.ID)
		delete(s.lostPackets, pkt.pn)
		s.stats.SpuriousLosses++
	}

	// Process live ACKs in ascending PN order so largestAcked only grows.
	sort.Slice(hits, func(i, j int) bool { return hits[i].pn < hits[j].pn })

	prevLargest := map[PathID]uint64{}
	newLargest := map[PathID]*packet{}

	for _, pkt := range hits {
		if pkt.acked {
			continue
		}
		pkt.acked = true
		delete(s.byPN, pkt.pn)
		// A frame that was scheduled for retransmission is now known to
		// have been delivered: cancel the pending retransmit.
		delete(s.scheduled, pkt.frame.ID)

		p, ok := s.paths[pkt.path]
		if !ok {
			continue
		}
		if pkt.migrating {
			s.removeMigrating(pkt)
			// No congestion credit for an abandoned path.
		} else {
			delete(p.outstanding, pkt.pn)
			p.cc.bytesInFlight -= pkt.size
			if p.cc.bytesInFlight < 0 {
				p.cc.bytesInFlight = 0
			}
			p.cc.onAck(pkt.pn, pkt.size)
		}
		s.stats.Acked++

		if _, seen := prevLargest[pkt.path]; !seen {
			prevLargest[pkt.path] = p.largestAcked
		}
		if pkt.pn > p.largestAcked {
			p.largestAcked = pkt.pn
			p.hasLargestAcked = true
		}
		if m := newLargest[pkt.path]; m == nil || pkt.pn > m.pn {
			newLargest[pkt.path] = pkt
		}
	}

	// RTT sampling (largest newly acked PN per path) and loss detection.
	for pid, pkt := range newLargest {
		p := s.paths[pid]
		if p == nil {
			continue
		}
		if pkt.pn > prevLargest[pid] {
			p.rtt.update(now.Sub(pkt.sentAt))
		}
		s.detectLostPath(p)
	}
}

// pickPath selects an active path with room in its congestion window. The
// connection-level cap counts only active paths; migrating bytes are excluded
// precisely so an invalidated path cannot deadlock the connection.
func (s *Sender) pickPath() *pathState {
	if s.cfg.MaxConnectionInFlight > 0 &&
		s.connInFlight()+MaxDatagramSize > s.cfg.MaxConnectionInFlight {
		return nil
	}
	var best *pathState
	bestAvail := 0
	for _, p := range s.paths {
		if !p.active {
			continue
		}
		avail := p.cc.cwnd - p.cc.bytesInFlight
		if avail < MaxDatagramSize {
			continue
		}
		if best == nil || avail > bestAvail || (avail == bestAvail && p.id < best.id) {
			best = p
			bestAvail = avail
		}
	}
	return best
}

func (s *Sender) connInFlight() int {
	total := 0
	for _, p := range s.paths {
		if p.active {
			total += p.cc.bytesInFlight
		}
	}
	return total
}

// Send produces the next datagram, retransmissions first. It returns false
// when there is no frame to send or no congestion capacity on an active path.
func (s *Sender) Send(now time.Time) (*Outgoing, bool) {
	s.CheckTimeouts(now)

	var fr Frame
	isRetx := false
	for len(s.retxOrder) > 0 {
		id := s.retxOrder[0]
		s.retxOrder = s.retxOrder[1:]
		if _, ok := s.scheduled[id]; !ok {
			continue // canceled by a late ACK
		}
		delete(s.scheduled, id)
		f, ok := s.frames[id]
		if !ok {
			continue
		}
		fr = f
		isRetx = true
		break
	}
	if !isRetx {
		if len(s.newFrames) == 0 {
			return nil, false
		}
		fr = s.newFrames[0]
		s.newFrames = s.newFrames[1:]
	}

	p := s.pickPath()
	if p == nil {
		if isRetx {
			s.scheduled[fr.ID] = true
			s.retxOrder = append([]uint64{fr.ID}, s.retxOrder...)
		} else {
			s.newFrames = append([]Frame{fr}, s.newFrames...)
		}
		return nil, false
	}

	pn := s.nextPN
	s.nextPN++
	pkt := &packet{pn: pn, path: p.id, sentAt: now, size: MaxDatagramSize, frame: fr}
	p.outstanding[pn] = pkt
	p.cc.bytesInFlight += pkt.size
	p.largestSent = pn
	s.byPN[pn] = pkt

	s.stats.Sent++
	if isRetx {
		s.stats.Retransmits++
	}
	return &Outgoing{Path: p.id, PN: pn, Frame: fr, Retx: isRetx}, true
}

// Stats returns a snapshot of the sender counters.
func (s *Sender) Stats() Stats { return s.stats }

// BytesInFlight returns the congestion-controlled bytes in flight on a path.
func (s *Sender) BytesInFlight(id PathID) int {
	if p, ok := s.paths[id]; ok {
		return p.cc.bytesInFlight
	}
	return 0
}

// MigratingCount returns the number of packets awaiting the migration grace.
func (s *Sender) MigratingCount() int { return len(s.migrating) }

// PendingFrames returns the number of unsent application frames.
func (s *Sender) PendingFrames() int { return len(s.newFrames) }

// ScheduledRetransmits returns the number of retransmissions queued but not
// yet sent (including those already canceled but not lazily removed).
func (s *Sender) ScheduledRetransmits() int { return len(s.scheduled) }
```

