func mkFrame(id uint64) Frame { return Frame{ID: id, Data: []byte{byte(id)}} }

// sendAll drains the sender until it refuses to produce more datagrams.
func sendAll(s *Sender, now time.Time) []*Outgoing {
	var out []*Outgoing
	for {
		o, ok := s.Send(now)
		if !ok {
			return out
		}
		out = append(out, o)
	}
}

// TestBasicTwoPath checks the happy path: independent paths, all ACKed, no
// retransmits, no spurious losses.
func TestBasicTwoPath(t *testing.T) {
	s := New(DefaultConfig())
	s.AddPath(PathA)
	s.AddPath(PathB)

	now := time.Unix(0, 0)
	for i := uint64(0); i < 10; i++ {
		if err := s.Enqueue(mkFrame(i)); err != nil {
			t.Fatal(err)
		}
	}
	out := sendAll(s, now)
	if len(out) != 10 {
		t.Fatalf("want 10 datagrams, got %d", len(out))
	}

	s.OnAck(now.Add(time.Second), AckFrame{Largest: 9, Ranges: []Range{{Smallest: 0, Largest: 8}}})

	if s.Stats().Acked != 10 {
		t.Fatalf("acked = %d, want 10", s.Stats().Acked)
	}
	if s.Stats().Retransmits != 0 {
		t.Fatalf("retransmits = %d, want 0", s.Stats().Retransmits)
	}
	if s.Stats().SpuriousLosses != 0 {
		t.Fatalf("spurious losses = %d, want 0", s.Stats().SpuriousLosses)
	}
}

// TestReorderedAckCancelsSpuriousRetransmit exercises the packet-threshold
// rule firing for PN0..2 because only PN5 is ACKed, followed by a delayed ACK
// for PN0..4. The queued retransmissions must be canceled; no retransmit is
// allowed to leave the sender.
func TestReorderedAckCancelsSpuriousRetransmit(t *testing.T) {
	s := New(DefaultConfig())
	s.AddPath(PathA)

	now := time.Unix(0, 0)
	for i := uint64(0); i < 6; i++ {
		if err := s.Enqueue(mkFrame(i)); err != nil {
			t.Fatal(err)
		}
	}
	if got := len(sendAll(s, now)); got != 6 {
		t.Fatalf("want 6 datagrams, got %d", got)
	}

	// Only PN5 is acknowledged. PN0..2 fall below the packet threshold and
	// are (prematurely) declared lost, queueing retransmissions.
	s.OnAck(now.Add(10*time.Millisecond), AckFrame{Largest: 5})
	if s.ScheduledRetransmits() != 3 {
		t.Fatalf("scheduled retransmits = %d, want 3", s.ScheduledRetransmits())
	}

	// The delayed ACK for PN0..4 races in before any retransmit is sent.
	s.OnAck(now.Add(20*time.Millisecond), AckFrame{Largest: 4, Ranges: []Range{{Smallest: 0, Largest: 3}}})

	if s.Stats().SpuriousLosses != 3 {
		t.Fatalf("spurious losses = %d, want 3", s.Stats().SpuriousLosses)
	}
	if len(s.byPN) != 0 {
		t.Fatalf("%d packets still in flight, want 0", len(s.byPN))
	}
	if s.ScheduledRetransmits() != 0 {
		t.Fatalf("scheduled retransmits = %d, want 0", s.ScheduledRetransmits())
	}

	o, ok := s.Send(now.Add(30 * time.Millisecond))
	if ok && o.Retx {
		t.Fatalf("spurious retransmit produced: %+v", o)
	}
	if s.Stats().Retransmits != 0 {
		t.Fatalf("retransmits = %d, want 0", s.Stats().Retransmits)
	}
}

// TestMigrationAckRaceNoSpuriousRetransmit checks that an ACK which arrives
// after a path is invalidated but before the migration grace period expires
// cancels the retransmission.
func TestMigrationAckRaceNoSpuriousRetransmit(t *testing.T) {
	s := New(DefaultConfig())
	s.AddPath(PathA)

	now := time.Unix(0, 0)
	for i := uint64(0); i < 4; i++ {
		if err := s.Enqueue(mkFrame(i)); err != nil {
			t.Fatal(err)
		}
	}
	if got := len(sendAll(s, now)); got != 4 {
		t.Fatalf("want 4 datagrams on path A, got %d", got)
	}

	s.InvalidatePath(now, PathA)
	s.AddPath(PathB) // the surviving path

	if s.MigratingCount() != 4 {
		t.Fatalf("migrating = %d, want 4", s.MigratingCount())
	}
	if s.BytesInFlight(PathA) != 0 {
		t.Fatalf("bytes in flight on dead path = %d, want 0", s.BytesInFlight(PathA))
	}

	// The peer's ACK arrives just after migration.
	s.OnAck(now.Add(10*time.Millisecond), AckFrame{Largest: 3, Ranges: []Range{{Smallest: 0, Largest: 2}}})

	if s.Stats().MigrationRetransmits != 0 {
		t.Fatalf("migration retransmits = %d, want 0", s.Stats().MigrationRetransmits)
	}
	if s.MigratingCount() != 0 {
		t.Fatalf("migrating = %d, want 0", s.MigratingCount())
	}
	if o, ok := s.Send(now.Add(20 * time.Millisecond)); ok && o.Retx {
		t.Fatalf("spurious retransmit after migration race: %+v", o)
	}
}

// TestMigrationTimeoutPreventsDeadlock checks the other side of the race: if
// the ACK never arrives, the grace timer must reschedule every frame on the
// surviving path. A connection-level in-flight cap makes the deadlock that
// would occur if migrating bytes were still counted explicit.
func TestMigrationTimeoutPreventsDeadlock(t *testing.T) {
	cfg := DefaultConfig()
	cfg.MaxConnectionInFlight = 4 * MaxDatagramSize // exactly the 4 frames we send
	s := New(cfg)
	s.AddPath(PathA)

	now := time.Unix(0, 0)
	for i := uint64(0); i < 4; i++ {
		if err := s.Enqueue(mkFrame(i)); err != nil {
			t.Fatal(err)
		}
	}
	if got := len(sendAll(s, now)); got != 4 {
		t.Fatalf("want 4 datagrams, got %d", got)
	}

	s.InvalidatePath(now, PathA)
	s.AddPath(PathB)

	// If the dead path's bytes were still counted, the connection cap would
	// be full (4*1200) and Send could never make progress.
	if s.connInFlight() != 0 {
		t.Fatalf("connection in-flight after migration = %d, want 0", s.connInFlight())
	}

	later := now.Add(time.Second) // well past the PTO grace period
	s.CheckTimeouts(later)
	if s.Stats().MigrationRetransmits != 4 {
		t.Fatalf("migration retransmits = %d, want 4", s.Stats().MigrationRetransmits)
	}

	var retx int
	for {
		o, ok := s.Send(later)
		if !ok {
			break
		}
		if o.Path != PathB {
			t.Fatalf("retransmit went to path %d, want path B", o.Path)
		}
		if o.Retx {
			retx++
		}
		later = later.Add(time.Millisecond)
	}
	if retx != 4 {
		t.Fatalf("retransmits on path B = %d, want 4", retx)
	}
}

// TestCrossPathReorderingDoesNotCauseLoss confirms that an ACK for a packet on
// one path cannot declare packets on the other path lost, even when the global
// packet numbers are interleaved.
func TestCrossPathReorderingDoesNotCauseLoss(t *testing.T) {
	s := New(DefaultConfig())
	s.AddPath(PathA)
	s.AddPath(PathB)

	now := time.Unix(0, 0)
	for i := uint64(0); i < 8; i++ {
		if err := s.Enqueue(mkFrame(i)); err != nil {
			t.Fatal(err)
		}
	}
	outs := sendAll(s, now)
	if len(outs) != 8 {
		t.Fatalf("want 8 datagrams, got %d", len(outs))
	}

	// Acknowledge all path-B packets as one ACK (PNs 1, 3, 5, largest 7).
	// Path-A outstanding packets must be untouched: loss detection is
	// per-path, so interleaved global PNs cannot cause cross-path losses.
	beforeA := len(s.paths[PathA].outstanding)
	s.OnAck(now.Add(10*time.Millisecond), AckFrame{
		Largest: 7,
		Ranges:  []Range{{Smallest: 1, Largest: 1}, {Smallest: 3, Largest: 3}, {Smallest: 5, Largest: 5}},
	})
	if s.ScheduledRetransmits() != 0 {
		t.Fatalf("cross-path ACK scheduled retransmits: %d", s.ScheduledRetransmits())
	}
	if got := len(s.paths[PathA].outstanding); got != beforeA {
		t.Fatalf("path A outstanding changed: %d -> %d", beforeA, got)
	}
}

// TestBoundedReorderingMemory confirms the recently-lost window never grows
// past its configured bound even under a long run of losses.
func TestBoundedReorderingMemory(t *testing.T) {
	cfg := DefaultConfig()
	cfg.MaxReorderingPackets = 8
	cfg.InitialCwnd = 100 * MaxDatagramSize
	s := New(cfg)
	s.AddPath(PathA)

	now := time.Unix(0, 0)
	for i := uint64(0); i < 100; i++ {
		if err := s.Enqueue(mkFrame(i)); err != nil {
			t.Fatal(err)
		}
	}
	sendAll(s, now)

	// Force the whole window to be declared lost via the packet threshold.
	s.OnAck(now.Add(10*time.Millisecond), AckFrame{Largest: 99})
	if len(s.lostPackets) > cfg.MaxReorderingPackets {
		t.Fatalf("lostPackets = %d, exceeds bound %d", len(s.lostPackets), cfg.MaxReorderingPackets)
	}
	if len(s.lostOrder) > cfg.MaxReorderingPackets {
		t.Fatalf("lostOrder = %d, exceeds bound %d", len(s.lostOrder), cfg.MaxReorderingPackets)
	}
}

// TestRandomizedStress drives the sender with random ACKs, random path
// invalidations and random timeouts, then checks the safety invariants and
// convergence.
func TestRandomizedStress(t *testing.T) {
	rng := rand.New(rand.NewSource(7))
	s := New(DefaultConfig())
	s.AddPath(PathA)
	s.AddPath(PathB)
	now := time.Unix(0, 0)

	const total = 300
	for i := uint64(0); i < total; i++ {
		if err := s.Enqueue(mkFrame(i)); err != nil {
			t.Fatal(err)
		}
	}

	ackAll := func(at time.Time) {
		if len(s.byPN) == 0 {
			return
		}
		var pns []uint64
		for pn := range s.byPN {
			pns = append(pns, pn)
		}
		sort.Slice(pns, func(i, j int) bool { return pns[i] < pns[j] })
		ack := AckFrame{Largest: pns[len(pns)-1]}
		for _, pn := range pns[:len(pns)-1] {
			ack.Ranges = append(ack.Ranges, Range{Smallest: pn, Largest: pn})
		}
		s.OnAck(at, ack)
	}

	for round := 0; round < 3000; round++ {
		now = now.Add(time.Millisecond)
		for {
			if _, ok := s.Send(now); !ok {
				break
			}
		}
		if rng.Intn(40) == 0 {
			id := PathID(rng.Intn(2))
			s.InvalidatePath(now, id)
			s.AddPath(id) // revive cleanly
		}
		if len(s.byPN) > 0 && rng.Intn(4) != 0 {
			ackAll(now)
		}
		for _, p := range s.paths {
			if p.cc.bytesInFlight < 0 {
				t.Fatalf("negative bytesInFlight on path %d: %d", p.id, p.cc.bytesInFlight)
			}
		}
		if len(s.lostPackets) > s.cfg.MaxReorderingPackets {
			t.Fatalf("lostPackets unbounded: %d", len(s.lostPackets))
		}
	}

	for round := 0; round < 5000; round++ {
		if len(s.byPN) == 0 && len(s.newFrames) == 0 && len(s.migrating) == 0 && len(s.scheduled) == 0 {
			break
		}
		now = now.Add(10 * time.Millisecond)
		for {
			if _, ok := s.Send(now); !ok {
				break
			}
		}
		ackAll(now)
	}
	if len(s.byPN) != 0 || len(s.newFrames) != 0 || len(s.migrating) != 0 {
		t.Fatalf("stress did not converge: inFlight=%d new=%d migrating=%d scheduled=%d",
			len(s.byPN), len(s.newFrames), len(s.migrating), len(s.scheduled))
	}
}
